CREATE FUNCTION public.library_history_family(s jsonb,r text,source text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT CASE WHEN source='wayback' AND (coalesce(public.library_number(s#>'{archive,fonts_failed}'),0)>0 OR s#>>ARRAY['type','rendered',r,'substituted']='true' OR coalesce(s#>>ARRAY['type','rendered',r,'webfont'],'false')<>'true') THEN coalesce(nullif(regexp_replace(regexp_replace(lower(split_part(CASE WHEN jsonb_typeof(s#>ARRAY['type','declared',r,'stack'])='array' THEN s#>>ARRAY['type','declared',r,'stack','0'] ELSE coalesce(s#>>ARRAY['type','declared',r,'stack'],s#>>ARRAY['type','declared',r,'family']) END,',',1)),'[^a-z0-9]','','g'),'(webfont|variable|display|text|web|vf|pro)+$','','g'),''),s#>>ARRAY['type','rendered',r,'family']) ELSE s#>>ARRAY['type','rendered',r,'family'] END; $$;
CREATE VIEW public.library_site_history WITH(security_invoker=true) AS WITH live AS (SELECT DISTINCT ON(domain) * FROM public.library_snapshots WHERE source='live' AND page_type='home' AND viewport='desktop' ORDER BY domain,captured_at DESC,id DESC), candidates AS (SELECT s.*,public.library_quarter(captured_at) quarter FROM public.library_snapshots s WHERE source='wayback' AND page_type='home' AND viewport='desktop' UNION ALL SELECT l.*,public.library_quarter(now()) FROM live l), samples AS (SELECT DISTINCT ON(domain,quarter) * FROM candidates ORDER BY domain,quarter,(source='live') DESC,captured_at DESC,id DESC) SELECT s.domain,s.quarter,s.captured_at,s.source,(s.source='live') AS now,s.id snapshot_id,l.sector,public.library_history_family(s.signals,'h1',s.source) h1_family,public.library_history_family(s.signals,'body',s.source) body_family,s.signals#>>'{color,theme}' theme,s.signals#>>'{color,accent}' accent,s.signals#>>'{color,page_bg}' page_bg,public.library_number(coalesce(s.signals#>'{composition,whitespace_ratio}',s.signals#>'{color,whitespace_ratio}')) whitespace_ratio,s.signals#>>'{layout,hero_media}' hero_media,public.library_number(s.signals#>'{layout,grid_max_cols}') grid_max_cols,CASE WHEN public.library_number(s.signals#>'{layout,cta_radius_px}')=0 THEN '0' WHEN public.library_number(s.signals#>'{layout,cta_radius_px}')<=8 THEN '1–8' WHEN public.library_number(s.signals#>'{layout,cta_radius_px}')<=24 THEN '9–24' WHEN public.library_number(s.signals#>'{layout,cta_radius_px}')>24 THEN 'pill' END cta_radius_bucket,coalesce(s.signals->'css_features','[]'::jsonb) css_features,coalesce(s.signals->'tech','{}'::jsonb) frameworks,CASE WHEN s.source='wayback' THEN public.library_history_family(s.signals,'body',s.source)!~* '^(systemui|serif|sansserif|arial|helvetica|georgia|timesnewroman|monospace)$' ELSE s.signals#>>'{type,rendered,body,webfont}'='true' END webfont,public.library_number(s.signals#>'{type,declared,h1,letter_spacing_em}') h1_tracking,CASE WHEN coalesce(public.library_number(t.tags->'confidence'),0)>=0.4 AND coalesce(t.tags->>'low_confidence','false')<>'true' AND t.tags->>'blocked_reason' IS NULL THEN t.tags ELSE '{}'::jsonb END ai_tags FROM samples s JOIN public.library_sites l USING(domain) LEFT JOIN public.library_tags t ON t.snapshot_id=s.id WHERE l.active=true;
GRANT SELECT ON public.library_site_history TO anon,authenticated,service_role;
CREATE VIEW public.library_history_share_live WITH(security_invoker=true) AS WITH scopes AS (SELECT h.*,sector scope FROM public.library_site_history h UNION ALL SELECT h.*,'all' FROM public.library_site_history h), features AS (SELECT DISTINCT jsonb_array_elements_text(css_features) feature FROM public.library_site_history UNION SELECT unnest(ARRAY['container_queries','has_selector','oklch','view_transitions','scroll_timeline','text_wrap_balance','subgrid','dvh_units'])), metrics AS (SELECT s.quarter,s.scope sector,s.domain,m.dimension,m.value,m.hit,m.measure FROM scopes s CROSS JOIN LATERAL (VALUES ('theme','dark',s.theme='dark',null::double precision),('headline','serif',s.h1_family ~* '(serif|georgia|times|garamond|canela|tiempos|lora|fraunces|playfair|editorial|domaine|recoleta)' AND s.h1_family !~* 'sans',null),('font','webfont',s.webfont,null),('font','system',NOT s.webfont,null),('tracking','tight',s.h1_tracking<=-0.02,null),('whitespace','median',null::boolean,s.whitespace_ratio)) m(dimension,value,hit,measure) UNION ALL SELECT quarter,scope,domain,'css',f.feature,css_features?f.feature,null FROM scopes CROSS JOIN features f UNION ALL SELECT quarter,scope,domain,'framework',f.flag,frameworks->>f.flag='true',null FROM scopes CROSS JOIN (VALUES('next'),('framer'),('webflow'),('tailwind')) f(flag) UNION ALL SELECT quarter,scope,domain,'hero_media',v.value,hero_media=v.value,null FROM scopes CROSS JOIN (SELECT DISTINCT hero_media value FROM public.library_site_history WHERE hero_media IS NOT NULL) v UNION ALL SELECT quarter,scope,domain,d.key,v.value,true,null FROM scopes CROSS JOIN LATERAL jsonb_each(ai_tags) d CROSS JOIN LATERAL jsonb_array_elements_text(CASE WHEN jsonb_typeof(d.value)='array' THEN d.value WHEN jsonb_typeof(d.value)='string' THEN jsonb_build_array(d.value) ELSE '[]'::jsonb END) v(value) WHERE d.key IN ('imagery','aesthetic','components','hero_layout','ai_positioning','tone','color_mood')), counts AS (SELECT quarter,scope sector,count(*) denom FROM scopes GROUP BY quarter,scope), vocabulary AS (SELECT DISTINCT dimension,value FROM metrics), calendar AS (SELECT public.library_quarter(d) quarter FROM generate_series('2021-01-01'::timestamptz,now(),interval '3 months') d), sectors AS (SELECT sector,count(*) active_sites FROM public.library_sites WHERE active=true GROUP BY sector UNION ALL SELECT 'all',count(*) FROM public.library_sites WHERE active=true), aggregated AS (SELECT quarter,sector,dimension,value,count(DISTINCT domain) FILTER(WHERE hit) sites,percentile_cont(0.5) WITHIN GROUP(ORDER BY measure) median FROM metrics GROUP BY quarter,sector,dimension,value) SELECT c.quarter,s.sector,v.dimension,v.value,coalesce(a.sites,0) sites,coalesce(n.denom,0) denom,CASE WHEN v.dimension='whitespace' THEN a.median ELSE coalesce(a.sites,0)::double precision/nullif(n.denom,0) END share,coalesce(n.denom,0)::double precision/nullif(s.active_sites,0) coverage FROM calendar c CROSS JOIN sectors s CROSS JOIN vocabulary v LEFT JOIN counts n ON n.quarter=c.quarter AND n.sector=s.sector LEFT JOIN aggregated a ON a.quarter=c.quarter AND a.sector=s.sector AND a.dimension=v.dimension AND a.value=v.value;
GRANT SELECT ON public.library_history_share_live TO service_role;
CREATE MATERIALIZED VIEW public.library_history_share_mat AS SELECT * FROM public.library_history_share_live;
CREATE UNIQUE INDEX library_history_share_mat_key ON public.library_history_share_mat(quarter,sector,dimension,value);
REVOKE ALL ON public.library_history_share_mat FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.library_history_share_mat TO service_role;
CREATE VIEW public.library_history_share AS SELECT * FROM public.library_history_share_mat;
GRANT SELECT ON public.library_history_share TO anon,authenticated,service_role;
CREATE VIEW public.library_history_fonts WITH(security_invoker=true) AS WITH fonts AS (SELECT DISTINCT domain,left(quarter,4)::integer AS year,r.role,r.family FROM public.library_site_history CROSS JOIN LATERAL (VALUES('h1',h1_family),('body',body_family)) r(role,family) WHERE r.family IS NOT NULL), counts AS (SELECT year,role,family,count(DISTINCT domain) sites FROM fonts GROUP BY year,role,family), ranked AS (SELECT *,row_number() OVER(PARTITION BY year,role ORDER BY sites DESC,family) AS rank FROM counts) SELECT * FROM ranked WHERE rank<=25;
GRANT SELECT ON public.library_history_fonts TO anon,authenticated,service_role;
CREATE VIEW public.library_redesigns WITH(security_invoker=true) AS SELECT extract(year FROM coalesce(e.effective_at,e.detected_at))::integer AS year,l.sector,e.source,count(*) redesigns FROM public.library_events e JOIN public.library_sites l USING(domain) WHERE e.type='redesign' GROUP BY 1,l.sector,e.source;
GRANT SELECT ON public.library_redesigns TO anon,authenticated,service_role;
DO $$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.refresh_library_history()'::regprocedure);d:=replace(d,'REFRESH MATERIALIZED VIEW public.library_signal_series_mat;','REFRESH MATERIALIZED VIEW public.library_history_share_mat; REFRESH MATERIALIZED VIEW public.library_signal_series_mat;');EXECUTE d; END $$;